import { describe, it, expect, beforeEach } from 'vitest';
import { parseCron } from '../src/cron.js';

const test = () => ({ minute: '0' });

describe('parseCron', () => {
  beforeEach(() => {});

  it('rejects a six-field expression with a bad day-of-week', () => {
    expect(() => parseCron('0 0 0 0 0 9')).toThrow(/day-of-week/);
  });

  it('accepts the standard five-field form', () => {
    expect(parseCron('*/5 * * * *')).toStrictEqual(test());
  });
});
